import{_ as a,o as i,c as t,a3 as o}from"./chunks/framework.1Y430-yj.js";const h=JSON.parse('{"title":"Production Control and Frontier Research","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"生产控制与前沿研究","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-0iirIEzxWlkfel2jMLIWJJ.md","filePath":"logistics/src/page-0iirIEzxWlkfel2jMLIWJJ.md","lastUpdated":null}'),n={name:"logistics/src/page-0iirIEzxWlkfel2jMLIWJJ.md"};function s(r,e,l,c,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="生产控制与前沿研究" aria-hidden="true"></span><h1 id="production-control-and-frontier-research" tabindex="-1">Production Control and Frontier Research <a class="header-anchor" href="#production-control-and-frontier-research" aria-label="Permalink to &quot;Production Control and Frontier Research&quot;">​</a></h1><blockquote><p>Source page ID: <code>0iirIEzxWlkfel2jMLIWJJ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-5515548b0ac8f945.q90-2df7f7103be0fb88.webp" alt="Production Control and Frontier Research"></p><p><span id="source-block-DWqjx1xibQYINqsd5UEFOm"></span></p><span class="logistics-source-anchor" id="阻塞生产原理-又名-爆仓动力学" aria-hidden="true"></span><h2 id="principles-of-production-controlled-by-blocking-a-k-a-full-storage-dynamics" tabindex="-1">Principles of Production Controlled by Blocking (a.k.a. Full-Storage Dynamics) <a class="header-anchor" href="#principles-of-production-controlled-by-blocking-a-k-a-full-storage-dynamics" aria-label="Permalink to &quot;Principles of Production Controlled by Blocking (a.k.a. Full-Storage Dynamics)&quot;">​</a></h2><p>(Coo coo coo... this large work is under construction. Graduation work is keeping me busy, so updates are slowing.)</p><p><a href="https://www.skland.com/article?id=6331180" target="_blank" rel="noreferrer">jnk&#39;s introductory article</a></p><p><a href="./page-MSyCxO1yMtqlXdUCG6Utsc">Explanation: Automatically Balanced Production Lines and Adaptive Devices</a></p><p>Author: kokobird (Sections 1–4). Contact me with questions.</p><details><summary>bilibili</summary><p>蓝海露花_kokobird. I rarely check bilibili, though; finding me in the group is easier.</p></details><p>Last updated: September 13, 2026.</p><p>Status: The planned basic content of Sections 1–2 is complete, though improvements will continue. Sections 3–4 are progressing slowly; also consult my related (pseudo-)paper PDFs and videos.</p><p><span id="source-block-rCxnzFpo8mWaztoa5WoVYx"></span></p><span class="logistics-source-anchor" id="_1-引言" aria-hidden="true"></span><h3 id="_1-introduction" tabindex="-1">1 Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1 Introduction&quot;">​</a></h3><p><span class="mark-rose_red">Welcome to the automatic-production classroom, Endministrator. Perhaps you have just built simple recipe-based lines and are eager for advanced material; perhaps you can already independently plan and lay out every region&#39;s factory and are idly browsing. Either way, I hope this article offers theoretical or practical inspiration in your spare time and shows the distinctive appeal of Endfield&#39;s industry. Perhaps someday you too will build an unusual production line and pioneer a new school of factory design.</span></p><p><a href="./page-quUTb9JSv879txqKEKI0BS">1.1 So Tell Me: What Is Production Controlled by Blocking?</a> · <a href="./page-vjw47WlrDGyaYlemKyfnH8">1.2 What Are Its Benefits?</a> · <a href="./page-FBJt940VrXTDHkr5w3g0v3">1.3 Glossary (Even I Cannot Fully Define These; You Can Skip It)</a> · <a href="./page-vU9euEi7t9vlO2SVM14zM9">1.4 Prerequisite Basics (To Be Written)</a></p><p><span id="source-block-9lRjFmYbvOxK5tFFbqXsuJ"></span></p><span class="logistics-source-anchor" id="_2-阻塞生产的基本概念与简单例子" aria-hidden="true"></span><h3 id="_2-basic-concepts-and-simple-examples-of-blocking-based-production" tabindex="-1">2 Basic Concepts and Simple Examples of Blocking-Based Production <a class="header-anchor" href="#_2-basic-concepts-and-simple-examples-of-blocking-based-production" aria-label="Permalink to &quot;2 Basic Concepts and Simple Examples of Blocking-Based Production&quot;">​</a></h3><p>This section introduces basic concepts and simple examples. Understanding it lets you design blocking-based production for <span class="mark-rose_red"><strong>multiple finished products from a single input material</strong></span>, meeting most simple automatic-production needs. <strong>If you believe you already know this material, read Section 2.5 directly; if you understand it, proceed straight to Section 3.</strong></p><p>One point worth making at the outset: discussing blocking-based production usually involves two stages, <span class="mark-rose_red"><strong>theoretical planning</strong></span> and <span class="mark-rose_red"><strong>engineering implementation</strong></span>. In <span class="mark-rose_red"><strong>theoretical planning</strong></span>, we discuss <u>which finished products to make, how much input is available, which processing steps are required, material routing and allocation, and priority design</u>. For example, demand analysis may tell us to assign X of 120 Ferrium to powder production and Y to Yazhen Syringe [C], but we are not yet especially concerned with how to build a line grinding X Ferrium.</p><p>In <span class="mark-rose_red"><strong>engineering implementation</strong></span>, we discuss <u>facility layout, the particular structures implementing priority, and structural optimization</u>. With sufficient <span class="mark-rose_red"><strong>theoretical planning</strong></span>, implementation usually amounts to wiring the planned connections. Optimizing those connections is outside this article&#39;s focus, though it still takes considerable skill. Most subsequent analysis therefore emphasizes <span class="mark-rose_red"><strong>theoretical planning</strong></span>; commonly used implementation structures appear in the appendix.</p><p><a href="./page-EtRfKcfCGHwRQxAFs7gkqI">2.1 Hello World: Ferrium Ore at a Fork in Its Fate</a> · <a href="./page-ZDxRoi4GKekmLzgHNaf4fQ">2.2 Two Blossoms: Switching-Type and Balancing-Type Blocking</a> · <a href="./page-t2SxyX0ruN8BvrYjwgoBde">2.3 The Controlled Controlled Branch and the Unfree Free Branch (Considering Retirement)</a></p><p>Note: I am considering replacing “controlled branch/free branch” with “blocking branch/flowing branch.” For splitting alone, an external restriction controls the controlled branch, which then controls the free branch. For merging, however, the direction reverses. Better to call them blocking/flowing branches and identify the control relationship separately. Later terminology has not yet been adjusted.</p><p><a href="./page-Bk5lLqDsnmVVaFwefNgViT">2.3 Blocking and Flowing Branches: You Control Me, I Control You</a> · <a href="./page-6aq5YsEznFHSQK7mwkc1Gm">2.4 “Faster-Than-Light” Upstream Propagation of Blocking Signals</a> · <a href="./page-o3yxqfGNALKamNYPO1eu1t">2.5 Isn&#39;t a Stash Just a Special Splitter? (Core Content ⭐)</a> · <a href="./page-LYKER2bG6lsxJFNfTATAAO">Practical Exercise: A Coupled Xircon–Yazhen Syringe [C] Line with 120 Ferrium</a> · <a href="./page-2kENbD6F4B8qcMtdPdudqt">2.6 Empty Storage? Full Storage? We Need More Oversupply!</a> · <a href="./page-IlngKiLhDJAlZSX3Qv1eGF">Appendix: Common Priority Structures</a></p><p><span id="source-block-x00nPzaklxsQ7IkqVngiau"></span></p><span class="logistics-source-anchor" id="_3-进阶阻塞生产" aria-hidden="true"></span><h3 id="_3-advanced-blocking-based-production" tabindex="-1">3 Advanced Blocking-Based Production <a class="header-anchor" href="#_3-advanced-blocking-based-production" aria-label="Permalink to &quot;3 Advanced Blocking-Based Production&quot;">​</a></h3><details><summary>There is advanced material too?!</summary><p>Congratulations, builder of great production lines. By reaching this point, you have learned the basic concepts of blocking-based production: roughly what it is and how to implement it. A wider world now opens before you. Rest a moment, then soar freely and enjoy the endless possibilities.</p></details><p>This section analyzes blocking-based solutions to harder demands, including <strong>adaptive balancing with multiple inputs and multiple products, and zero-waste blocking-based production using Solid-Gas and Fluid-Gas Transmuting Units</strong>. Understanding it helps you combine these principles with new demands introduced by updates, meet more complex production needs, and understand the dynamics of blocking-based production more deeply.</p><details><summary>The paper discusses most of Sections 3–4 in greater detail</summary><p><a href="/endfield-logistics-wiki/logistics/src/assets/attachments/%E6%BA%A2%E6%B5%81%E4%BE%9B%E6%96%99%E7%B3%BB%E7%BB%9F%E7%9A%84%E5%8A%A8%E5%8A%9B%E5%AD%A6%E4%B8%8E%E7%A8%B3%E5%AE%9A%E6%80%A7v2.pdf-4f2e850e4820968c.pdf" data-original-resource="true">Attachment: Dynamics and Stability of Overflow Supply Systems v2.pdf</a></p><blockquote><p>Original: 溢流供料系统的动力学与稳定性v2.pdf; size: 2910720; objKey: <code>60e2194df39147af852543a7e54218e2</code>; local status: available locally; attachment content has not been translated.</p></blockquote><p>Updated to v3 on 2026/9/9: richer content, more rigorous presentation, <s>more tiring to read</s>. You can begin directly with Part One, whose opening rigorously abstracts the mathematical model.</p><p><a href="/endfield-logistics-wiki/logistics/src/assets/attachments/%E6%BA%A2%E6%B5%81%E4%BE%9B%E6%96%99%E7%B3%BB%E7%BB%9F%E7%9A%84%E5%8A%A8%E5%8A%9B%E5%AD%A6%E4%B8%8E%E7%A8%B3%E5%AE%9A%E6%80%A7v3.pdf-42361709e96659db.pdf" data-original-resource="true">Attachment: Dynamics and Stability of Overflow Supply Systems v3.pdf</a></p><blockquote><p>Original: 溢流供料系统的动力学与稳定性v3.pdf; size: 4337949; objKey: <code>172aa5bd73d04fc390b7d009a19835e5</code>; local status: available locally; attachment content has not been translated.</p></blockquote></details><p><a href="./page-lZhn9NxeSAXQ7W0ANuqKFR">3.0 Balancing, Adaptive Operation, Maximum-Value Output—What Are You Babbling About?</a> · <a href="./page-KHooQBQESX74amkILMa8UI">3.1 The Beginnings of Automatic Balancing: Xiranite and Originium Powder&#39;s Love–Hate Relationship</a> · <a href="./page-SpFI2A6dCHUMgJI8KqPSP2">3.2 The Highest Mountain?! Heavy Xiranite AND Pyrrolite</a> · <a href="./page-PiMuthOkzu4i6PbMZSv662">3.3 You... You Xiranite-Gobbling Pig!</a></p><p><span id="source-block-V0u4t2MI93uTva23MwciTO"></span></p><span class="logistics-source-anchor" id="_3-4-中电池满仓切换低电池-赫铜满仓切换灼铜等" aria-hidden="true"></span><h4 id="_3-4-switch-from-sc-to-lc-batteries-when-sc-storage-fills-from-hetonite-to-pyrrolite-when-hetonite-storage-fills-etc" tabindex="-1">3.4 Switch from SC to LC Batteries When SC Storage Fills, from Hetonite to Pyrrolite When Hetonite Storage Fills, etc. <a class="header-anchor" href="#_3-4-switch-from-sc-to-lc-batteries-when-sc-storage-fills-from-hetonite-to-pyrrolite-when-hetonite-storage-fills-etc" aria-label="Permalink to &quot;3.4 Switch from SC to LC Batteries When SC Storage Fills, from Hetonite to Pyrrolite When Hetonite Storage Fills, etc.&quot;">​</a></h4><p><a href="https://www.bilibili.com/video/BV1Ecu66TEiv" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Ecu66TEiv</a></p><p><a href="https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7</a></p><p><span id="source-block-q8wRFhJsdttOEPgUXXKzWs"></span></p><span class="logistics-source-anchor" id="_4-阻塞生产中的若干动力学问题" aria-hidden="true"></span><h3 id="_4-some-dynamical-problems-in-blocking-based-production" tabindex="-1">4 Some Dynamical Problems in Blocking-Based Production <a class="header-anchor" href="#_4-some-dynamical-problems-in-blocking-based-production" aria-label="Permalink to &quot;4 Some Dynamical Problems in Blocking-Based Production&quot;">​</a></h3><p>This section offers theoretical numerical analysis and mathematical derivations/proofs of conclusions used in production design. Designing blocking-based lines does not require mastering it; knowing the conclusions suffices.</p><p><a href="./page-SI1crfpBOI1mEcT4TsqTBX">4.0 Building the Edifice of Blocking-Based Production on Blocking-Flow Theory (Slow Updates)</a> · <a href="./page-p8Q45DjLw7ZZB74NhCzwor">4.1 Modeling Production Dynamics: From Discrete and Continuous Models to Machine Dynamical Systems</a></p><p><span id="source-block-3S8rTspXHBNgZC5nPm6zvV"></span></p><span class="logistics-source-anchor" id="_4-2-两种原料两种成品的稳定性条件与分流区间" aria-hidden="true"></span><h4 id="_4-2-stability-conditions-and-splitting-ranges-for-two-inputs-and-two-products" tabindex="-1">4.2 Stability Conditions and Splitting Ranges for Two Inputs and Two Products <a class="header-anchor" href="#_4-2-stability-conditions-and-splitting-ranges-for-two-inputs-and-two-products" aria-label="Permalink to &quot;4.2 Stability Conditions and Splitting Ranges for Two Inputs and Two Products&quot;">​</a></h4><p><span id="source-block-FlCfyo96lld68gvkvF5hkf"></span></p><span class="logistics-source-anchor" id="_4-3-中间原料的情形-分离芯" aria-hidden="true"></span><h4 id="_4-3-intermediate-inputs-separator-core" tabindex="-1">4.3 Intermediate Inputs (Separator Core) <a class="header-anchor" href="#_4-3-intermediate-inputs-separator-core" aria-label="Permalink to &quot;4.3 Intermediate Inputs (Separator Core)&quot;">​</a></h4><p>A typical current example involving an intermediate input is Separator Core. As shown below, Pyrrolite requires Separator Core + Xiranite (gas) + Cuprium; Heavy Xiranite requires Separator Core + Xiranite (gas).</p><p>See Section 3.2 for the production design. Here we discuss only the mathematics.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/diagrams/flow-4d55ed00ef23efbb.q90-401539128a7401bb.webp" alt="Flowchart (source block XU0rAD0t41nCGvQD2UE8yG)"></p><blockquote><p>Exported from the source document&#39;s flowchart block. If no screenshot is provided locally, return to the source document for the interactive version.</p></blockquote><p><span id="source-block-u8XouKPIpUolO8tW4jkRhK"></span></p><span class="logistics-source-anchor" id="_4-4-多种原料多种成品的情形" aria-hidden="true"></span><h4 id="_4-4-multiple-inputs-and-multiple-products" tabindex="-1">4.4 Multiple Inputs and Multiple Products <a class="header-anchor" href="#_4-4-multiple-inputs-and-multiple-products" aria-label="Permalink to &quot;4.4 Multiple Inputs and Multiple Products&quot;">​</a></h4><p><span id="source-block-sjN1ulZ3iQZXduIRPWdnao"></span></p><span class="logistics-source-anchor" id="_4-5-达到稳定前的暂态过程的时间估计-振荡周期计算" aria-hidden="true"></span><h4 id="_4-5-estimating-the-transient-time-before-stability-and-calculating-oscillation-periods" tabindex="-1">4.5 Estimating the Transient Time Before Stability and Calculating Oscillation Periods <a class="header-anchor" href="#_4-5-estimating-the-transient-time-before-stability-and-calculating-oscillation-periods" aria-label="Permalink to &quot;4.5 Estimating the Transient Time Before Stability and Calculating Oscillation Periods&quot;">​</a></h4><p><a href="./page-wS5pCdiNNL0UXUvUi1A1Ak">4.6 Equivalence Between Adaptive Operation and Solving Linear Systems</a> · <a href="./page-3OgX0KC4XlwuN9q7grkcjS">ko鸟’s Workshop</a></p><p><span id="source-block-X2BQguP94yFfFweLbHLcF1"></span></p><span class="logistics-source-anchor" id="零激活物浪费到更广泛的自适应" aria-hidden="true"></span><h2 id="from-zero-activator-waste-to-broader-adaptive-operation" tabindex="-1">From Zero Activator Waste to Broader Adaptive Operation <a class="header-anchor" href="#from-zero-activator-waste-to-broader-adaptive-operation" aria-label="Permalink to &quot;From Zero Activator Waste to Broader Adaptive Operation&quot;">​</a></h2><blockquote><p>Detailed device explanations have moved to <a href="./page-kXUgC0EOTqKh09bVHL9EPN">Some Simpler Adaptive Setups</a>.</p></blockquote><p>“<strong>Switch between two states through a blocking signal</strong>, itself controlled by the remaining inventory, thereby forming feedback. The final result is stable oscillation: the relative times spent producing and stopped <strong>adaptively establish the required ratio</strong>.” — kokobird</p><p><span id="source-block-mMMJhvpB2nsi8tOedocEpS"></span></p><span class="logistics-source-anchor" id="大周期反应震荡" aria-hidden="true"></span><h2 id="long-period-reaction-oscillation" tabindex="-1">Long-Period Reaction Oscillation <a class="header-anchor" href="#long-period-reaction-oscillation" aria-label="Permalink to &quot;Long-Period Reaction Oscillation&quot;">​</a></h2><p>This topic requires either of two premises (feasibility: 1&gt;2):</p><p>1. The production side&#39;s range of adaptation to inputs covers the oscillation between both states. 2. Additional buffering lets machines consume stored inputs during accumulation, and excessive machine input does not waste material. (There is a risk of the control being overwhelmed.)</p><p>We have three signal-detection methods: the <strong>full-storage signal</strong> and <strong>empty-storage signal</strong>, which detect depot inventory, and a manually controlled <strong>clock signal</strong>. Pairing them produces long-period oscillations that keep inputs in storage. This reduces the additional unloaders needed for balancing with empty storage, and also reduces losses where direct full-storage overflow, affected by the withdrawal waveform, prevents material being deposited at its origin.</p><p><span id="source-block-RbO6Tb93wuoHSR4UjEgOUb"></span></p><span class="logistics-source-anchor" id="满仓-时钟控制" aria-hidden="true"></span><h3 id="full-storage–clock-control" tabindex="-1">Full-Storage–Clock Control <a class="header-anchor" href="#full-storage–clock-control" aria-label="Permalink to &quot;Full-Storage–Clock Control&quot;">​</a></h3><p>Design sequence: detect failure to deposit into storage (full) → admit reaction inputs and increase consumption → store the signal in a clock and delay it → stop the reaction and begin accumulation. This is one operating cycle.</p><p>Diagram:</p><p><span id="source-block-qGkAB86pF3OMhnOvn3sHBM"></span></p><span class="logistics-source-anchor" id="空仓-时钟控制" aria-hidden="true"></span><h3 id="empty-storage–clock-control" tabindex="-1">Empty-Storage–Clock Control <a class="header-anchor" href="#empty-storage–clock-control" aria-label="Permalink to &quot;Empty-Storage–Clock Control&quot;">​</a></h3><p>Design sequence: detect a gap in withdrawal (empty storage) → block reaction inputs and begin accumulation → store the signal in a clock and delay it → start the reaction and increase consumption. This is one operating cycle.</p><p>Diagram:</p><p><span id="source-block-xCX4qF1TzuYffAYgPKb9Pg"></span></p><span class="logistics-source-anchor" id="满仓-空仓控制" aria-hidden="true"></span><h3 id="full-storage–empty-storage-control" tabindex="-1">Full-Storage–Empty-Storage Control <a class="header-anchor" href="#full-storage–empty-storage-control" aria-label="Permalink to &quot;Full-Storage–Empty-Storage Control&quot;">​</a></h3><p>Design sequence: detect failure to deposit (full storage) → admit reaction inputs and increase consumption → detect a gap in withdrawal (empty storage) → block reaction inputs and begin accumulation. This is one operating cycle.</p><p>Diagram:</p><p><span id="source-block-Bu1wyct41RhwxXeUeBGarA"></span></p><span class="logistics-source-anchor" id="时钟-时钟控制" aria-hidden="true"></span><h3 id="clock–clock-control" tabindex="-1">Clock–Clock Control <a class="header-anchor" href="#clock–clock-control" aria-label="Permalink to &quot;Clock–Clock Control&quot;">​</a></h3><p><s>This seems bizarre, buddy. Why not simply rate-limit to 30p/q unit/min.jpg</s></p><p>Following the preceding discussion, add clocks both before and after blocking. This effectively controls accumulation duration T1 s and overconsumption duration T2 s. The controlled factory consumes at v unit/min. T1 and T2 can be changed through the clock structures and contents. For identical structures, assuming a constant signal-propagation delay t s, consumption is vT2/(T1+T2+t) unit/min, allowing some degree of p/q consumption limiting.</p><hr><p>The following is the group owner&#39;s responsibility.</p><p><span id="source-block-YZ6VeUpQiBgrSopI5kB9Ua"></span></p><span class="logistics-source-anchor" id="数字电路控制系统" aria-hidden="true"></span><h2 id="digital-circuit-control-system" tabindex="-1">Digital-Circuit Control System <a class="header-anchor" href="#digital-circuit-control-system" aria-label="Permalink to &quot;Digital-Circuit Control System&quot;">​</a></h2><p><span id="source-block-EnP43uHPu7gRUdMRKQOpSk"></span></p><span class="logistics-source-anchor" id="周期点信号的生成" aria-hidden="true"></span><h3 id="generating-periodic-point-signals" tabindex="-1">Generating Periodic Point Signals <a class="header-anchor" href="#generating-periodic-point-signals" aria-label="Permalink to &quot;Generating Periodic Point Signals&quot;">​</a></h3><p>As shown, <a href="./page-8XrtahEh9tfuCux72hbfbI#source-block-7R9931VccE38fQGWecdJ9R">Basic Factory Principles</a> allows one Ferrium Ore output every 100 seconds.</p><p>Define a downstream-flowing logistics stream called a point-signal stream. Once stable, every downstream output interval is a multiple of the largest possible fixed interval T, where T is quite large. The Ferrium Ore line above is plainly such a stream, with T = 100s. Call T its clock period and 1/T its clock frequency f, here 10mHz.</p><p><span id="source-block-z2Za4dfyLVXsRqMMoPrgK3"></span></p><span class="logistics-source-anchor" id="时钟采样" aria-hidden="true"></span><h3 id="clock-sampling" tabindex="-1">Clock Sampling <a class="header-anchor" href="#clock-sampling" aria-label="Permalink to &quot;Clock Sampling&quot;">​</a></h3><p>Feedback requires converting the source&#39;s flow state into digital signals 0 and 1, with 0 meaning inactive and 1 active. One idea is to regularize the source output, concentrating its output within each clock period into the same part of that period, for example:</p><p>1010101010——&gt;1110011000</p><p>The result in <a href="./page-Ul3PjfHfEH7t9ofd3SfA1L#source-block-f5f4WE5OyQHLDbhWbKgmAv">Logistics Principles and Frontier Research</a> lets us construct the illustrated device to meet this requirement.</p><p>Sampling one point in a clock period then compares the source&#39;s total output over an interval with a set value: greater output gives sample 1; otherwise 0. The sample point&#39;s position within the clock period determines this threshold.</p><p>The sampling device is easy to build, as shown:</p><p><span id="source-block-JuE8e1LcfMB49QplhfUWqT"></span></p><span class="logistics-source-anchor" id="信号放大" aria-hidden="true"></span><h3 id="signal-amplification" tabindex="-1">Signal Amplification <a class="header-anchor" href="#signal-amplification" aria-label="Permalink to &quot;Signal Amplification&quot;">​</a></h3><p>We sometimes need multiple uses of a point signal. Applying binary complementation twice copies a flow. This can be integrated into the following signal amplifier, each output producing a copied signal:</p><p><span id="source-block-HHuZkGBvhHGd7puOwrgATO"></span></p><span class="logistics-source-anchor" id="信号运算" aria-hidden="true"></span><h3 id="signal-operations" tabindex="-1">Signal Operations <a class="header-anchor" href="#signal-operations" aria-label="Permalink to &quot;Signal Operations&quot;">​</a></h3><p>Protocol Stash priorities permit logical operations on point signals, following exactly the simple-logic rules in <a href="./page-8XrtahEh9tfuCux72hbfbI#source-block-EHhBNcPi9z2GuxnXC3X587">Basic Factory Principles</a>. Here 1 means the point-signal stream outputs one item in the clock period, and 0 means no item.</p><p>Take particular care: if no AND follows the final NOT, the resulting signal is an almost-full complementary belt and fails the point-signal requirement. Add an AND with a high-level signal.</p><p><span id="source-block-x3ZJ3xNYB6VgMGagCAaz3A"></span></p><span class="logistics-source-anchor" id="信号还原" aria-hidden="true"></span><h3 id="signal-reconstruction" tabindex="-1">Signal Reconstruction <a class="header-anchor" href="#signal-reconstruction" aria-label="Permalink to &quot;Signal Reconstruction&quot;">​</a></h3><p>After logical operations, convert the result into output. Here an output signal means downstream will not continuously receive reaction inputs in the current period. The illustrated device performs this function:</p><p>When Ferrium Ore representing the computed output enters the Protocol Stash, the stash blocks and batteries cannot pass through. Its complementary belt reaches the stash output after a one-period delay. If the computed signal has stopped, Ferrium Ore exits, unblocking the stash, and batteries output continuously during the next period. Otherwise Ferrium Ore enters and exits simultaneously, leaving one Ferrium Ore in the stash; blocking persists and batteries cannot output.</p><p><span id="source-block-fc6GxHsFbpcKbKS9i9cPX6"></span></p><span class="logistics-source-anchor" id="利用延时器来改善性能" aria-hidden="true"></span><h3 id="improving-performance-with-delay-devices" tabindex="-1">Improving Performance with Delay Devices <a class="header-anchor" href="#improving-performance-with-delay-devices" aria-label="Permalink to &quot;Improving Performance with Delay Devices&quot;">​</a></h3><p>The filter in <a href="./page-Ul3PjfHfEH7t9ofd3SfA1L#source-block-f5f4WE5OyQHLDbhWbKgmAv">Logistics Principles and Frontier Research</a> uses very many reaction components and considerable space, making practical use difficult. Signal reconstruction also needs a one-period delay, requiring a very long belt. A flow limiter with internal circulation can supply a delay; this, for example, is a 100s delay device:</p><p>It simplifies the reconstruction delay. A high-level point signal of period 2T together with a signal reconstruction device delayed by T can produce a standard square wave of period 2T. With this square wave, the sampler&#39;s filter can be simplified as follows, greatly reducing its footprint and component count:</p></div>',1)])])}const g=a(n,[["render",s]]);export{h as __pageData,g as default};
